                "rootfs=$1\ncmdline=$2\nmount_log=$3\nruntime=$4\n"
                "share_mountpoints=\n"
                'mount() { printf "mount %s\\n" "$*" >>"$mount_log"; '
                'case "$*" in *shares/1*) return 1 ;; esac; }\n'
                'umount() { printf "umount %s\\n" "$1" >>"$mount_log"; }\n'
