class CleanupAfterKillTests(unittest.TestCase):
    """A failure path keeps its error when OpenVMM outlives its kill."""

    class StuckInteraction:
        """An OpenVMM that printed ``console`` and outlives its kill, whose
        output reader, with ``reader_stuck``, doesn't stop either."""

        def __init__(self, console: bytes, reader_stuck: bool = False) -> None:
            self.process = MagicMock(pid=4321)
            self.process.poll.return_value = None
            self.console = console
            self.reader_stuck = reader_stuck
            self.closed = False
            self.closes = 0

        def read_output(self, chunks: queue.Queue[bytes | None]) -> None:
            chunks.put(self.console)

        def read_stderr(self, chunks: queue.Queue[bytes | None]) -> None:
            del chunks

        def write_input(self, data: bytes) -> None:
            raise AssertionError(f"unexpected input: {data!r}")

        def close(self) -> None:
            self.closed = True
            self.closes += 1
            if self.reader_stuck:
                raise RuntimeError("OpenVMM output reader did not stop")

    EXIT_TIMEOUT = "process 4321 did not exit within 30s of being killed"
    READER_STUCK = "RuntimeError: OpenVMM output reader did not stop"

    def outliving_kill(self) -> Any:
        def outlive(*_args: object, **_kwargs: object) -> None:
            raise benchmark.ProcessExitTimeout(self.EXIT_TIMEOUT)

        return patch.object(benchmark, "terminate", side_effect=outlive)

    def test_a_launch_failure_keeps_its_error_when_openvmm_outlives_the_kill(self):
        with (
            patch.object(
                benchmark,
                "InteractiveProcess",
                return_value=self.StuckInteraction(b"booting\n"),
            ),
            patch.object(benchmark, "OUTPUT_DRAIN_TIMEOUT_SECONDS", 0.05),
            self.outliving_kill() as terminate,
            self.assertRaises(RuntimeError) as raised,
        ):
            benchmark.measure_once(["openvmm"], environment={}, timeout=0.2)

        terminate.assert_called_once()
        self.assertEqual(
            str(raised.exception),
            "guest marker was not observed within 0.2s\n"
            "--- OpenVMM output ---\nbooting\n\n"
            f"--- cleanup failures ---\n- ProcessExitTimeout: {self.EXIT_TIMEOUT}",
        )
        self.assertIsInstance(raised.exception.__cause__, TimeoutError)

    def test_a_guest_failure_report_survives_an_openvmm_that_outlives_the_kill(self):
        with (
            patch.object(
                benchmark,
                "InteractiveProcess",
                return_value=self.StuckInteraction(b"NVX-TEST-FAIL broken\n"),
            ),
            patch.object(benchmark, "OUTPUT_DRAIN_TIMEOUT_SECONDS", 0.05),
            self.outliving_kill() as terminate,
            self.assertRaises(benchmark.GuestFailureReported) as reported,
        ):
            benchmark.measure_once(
                ["openvmm"],
                environment={},
                timeout=5,
                failure_marker=b"NVX-TEST-FAIL",
            )

        terminate.assert_called_once()
        self.assertEqual(reported.exception.line, "NVX-TEST-FAIL broken")
        self.assertTrue(
            str(reported.exception).endswith(
                f"\n--- cleanup failures ---\n- ProcessExitTimeout: {self.EXIT_TIMEOUT}"
            ),
            str(reported.exception),
        )

    def test_a_teardown_timeout_kills_an_openvmm_that_outlives_the_kill_once(self):
        with (
            patch.object(
                benchmark,
                "InteractiveProcess",
                return_value=self.StuckInteraction(benchmark.BOOT_MARKER + b"\n"),
            ),
            patch.object(benchmark, "OUTPUT_DRAIN_TIMEOUT_SECONDS", 0.05),
            patch.object(benchmark, "live_peak_rss_bytes", return_value=1024),
            patch.object(
                benchmark,
                "wait_for_process_exit",
                side_effect=subprocess.TimeoutExpired("openvmm", 15),
            ),
            self.outliving_kill() as terminate,
            self.assertRaises(RuntimeError) as raised,
        ):
            benchmark.measure_once(
                ["openvmm"], environment={}, timeout=5, guest_exit_prequeued=True
            )

        terminate.assert_called_once()
        self.assertTrue(
            str(raised.exception).startswith(
                f"{self.EXIT_TIMEOUT}\n--- OpenVMM output ---\n"
            ),
            str(raised.exception),
        )

    def test_cleanup_runs_every_step_and_keeps_the_error_that_it_follows(self):
        calls: list[str] = []

        def step(name: str, error: Exception | None = None) -> Callable[[], None]:
            def run() -> None:
                calls.append(name)
                if error is not None:
                    raise error

            return run

        failure = ValueError("scenario failed")
        benchmark.append_cleanup_failures(
            failure, [benchmark.ProcessExitTimeout(self.EXIT_TIMEOUT)]
        )
        benchmark.finish_cleanup(
            failure,
            step("log", OSError("disk full")),
            None,
            step("close", RuntimeError("OpenVMM output reader did not stop")),
        )
        self.assertEqual(calls, ["log", "close"])
        # The failures join the kill's under one heading.
        self.assertEqual(
            str(failure),
            "scenario failed\n--- cleanup failures ---\n"
            f"- ProcessExitTimeout: {self.EXIT_TIMEOUT}\n- OSError: disk full\n"
            f"- {self.READER_STUCK}",
        )
        # Without an error to follow, the first failure surfaces with the others.
        with self.assertRaises(OSError) as raised:
            benchmark.finish_cleanup(
                None,
                step("log", OSError("disk full")),
                step("close", RuntimeError("OpenVMM output reader did not stop")),
            )
        self.assertEqual(
            str(raised.exception),
            f"disk full\n--- cleanup failures ---\n- {self.READER_STUCK}",
        )
        benchmark.finish_cleanup(None, step("close"))

    def test_cleanup_failures_reach_an_error_whose_message_has_an_errno(self):
        # An OSError with an errno takes its message from its errno, not its
        # arguments, so its failures go into an OSError that it caused.
        def full() -> OSError:
            return OSError(errno.ENOSPC, "No space left on device", "source.log")

        def fail(error: BaseException) -> Callable[[], None]:
            def run() -> None:
                raise error

            return run

        original = full()
        combined = benchmark.append_cleanup_failures(
            original, [RuntimeError("OpenVMM output reader did not stop")]
        )
        expected = f"{full()}\n--- cleanup failures ---\n- {self.READER_STUCK}"
        self.assertIs(type(combined), OSError)
        self.assertIs(combined.__cause__, original)
        self.assertEqual(str(combined), expected)
        self.assertEqual(str(original), str(full()))
        # A cleanup whose first failure is such an error raises the combined
        # one, and so does a cleanup that follows such an error.
        reader = RuntimeError("OpenVMM output reader did not stop")
        with self.assertRaises(OSError) as raised:
            benchmark.finish_cleanup(None, fail(full()), fail(reader))
        self.assertEqual(str(raised.exception), expected)
        with self.assertRaises(OSError) as raised:
            try:
                raise full()
            except OSError as failure:
                reader = RuntimeError("OpenVMM output reader did not stop")
                benchmark.finish_cleanup(failure, fail(reader))
                raise
        self.assertEqual(str(raised.exception), expected)
        self.assertIsInstance(raised.exception.__cause__, OSError)

    def test_a_launch_failure_keeps_its_error_when_the_reader_does_not_stop_either(
        self,
    ):
        with (
            patch.object(
                benchmark,
                "InteractiveProcess",
                return_value=self.StuckInteraction(b"booting\n", reader_stuck=True),
            ),
            patch.object(benchmark, "OUTPUT_DRAIN_TIMEOUT_SECONDS", 0.05),
            self.outliving_kill() as terminate,
            self.assertRaises(RuntimeError) as raised,
        ):
            benchmark.measure_once(["openvmm"], environment={}, timeout=0.2)

        terminate.assert_called_once()
        self.assertEqual(
            str(raised.exception),
            "guest marker was not observed within 0.2s\n"
            "--- OpenVMM output ---\nbooting\n\n"
            f"--- cleanup failures ---\n- ProcessExitTimeout: {self.EXIT_TIMEOUT}\n"
            f"- {self.READER_STUCK}",
        )
        self.assertIsInstance(raised.exception.__cause__, TimeoutError)

    def test_a_snapshot_capture_keeps_its_error_and_log_past_a_stuck_reader(self):
        with tempfile.TemporaryDirectory() as temporary:
            log_path = Path(temporary) / "source.log"
            with (
                patch.object(
                    benchmark,
                    "InteractiveProcess",
                    return_value=self.StuckInteraction(b"booting\n", reader_stuck=True),
                ),
                self.outliving_kill() as terminate,
                self.assertRaises(RuntimeError) as raised,
            ):
                benchmark.capture_device_restore_snapshot(
                    ["openvmm"],
                    Path(temporary) / "snapshot",
                    "blk",
                    "cold",
                    timeout=0.2,
                    log_path=log_path,
                )

            terminate.assert_called_once()
            # The log is written before the interaction's shutdown fails.
            self.assertEqual(log_path.read_bytes(), b"booting\n")
        self.assertEqual(
            str(raised.exception),
            "blk/cold source snapshot did not finish within 0.2s\n"
            "--- OpenVMM output ---\nbooting\n\n"
            f"--- cleanup failures ---\n- ProcessExitTimeout: {self.EXIT_TIMEOUT}\n"
            f"- {self.READER_STUCK}",
        )
        self.assertIsInstance(raised.exception.__cause__, TimeoutError)

    def test_an_openvmm_process_closes_and_keeps_its_error_past_a_failed_kill(self):
        interaction = self.StuckInteraction(b"booting\n")
        with tempfile.TemporaryDirectory() as temporary:
            log_path = Path(temporary) / "process.log"
            with (
                patch.object(
                    openvmm_process, "InteractiveProcess", return_value=interaction
                ),
                self.outliving_kill() as terminate,
                self.assertRaises(RuntimeError) as raised,
                openvmm_process.OpenvmmProcess(["openvmm"], log_path) as process,
            ):
                process.wait_for(b"NEVER", 0.2)

            terminate.assert_called_once()
            self.assertTrue(interaction.closed)
            self.assertEqual(log_path.read_bytes(), b"booting\n")
        self.assertEqual(
            str(raised.exception),
            "marker b'NEVER' was not observed within 0.2s\n"
            "--- OpenVMM output ---\nbooting\n\n"
            f"--- cleanup failures ---\n- ProcessExitTimeout: {self.EXIT_TIMEOUT}",
        )

    def test_an_openvmm_process_reports_a_failed_kill_after_its_block(self):
        interaction = self.StuckInteraction(b"booting\n")
        with tempfile.TemporaryDirectory() as temporary:
            log_path = Path(temporary) / "process.log"
            with (
                patch.object(
                    openvmm_process, "InteractiveProcess", return_value=interaction
                ),
                self.outliving_kill(),
            ):
                # A block that leaves OpenVMM running fails only on the kill.
                with self.assertRaisesRegex(
                    benchmark.ProcessExitTimeout, f"^{re.escape(self.EXIT_TIMEOUT)}$"
                ):
                    with openvmm_process.OpenvmmProcess(["openvmm"], log_path):
                        pass
                # The error that leaves a block stays the one that surfaces.
                with self.assertRaises(ValueError) as raised:
                    with openvmm_process.OpenvmmProcess(["openvmm"], log_path):
                        raise ValueError("scenario failed")
        self.assertEqual(
            str(raised.exception),
            "scenario failed\n--- cleanup failures ---\n"
            f"- ProcessExitTimeout: {self.EXIT_TIMEOUT}",
        )

    def test_an_openvmm_process_keeps_its_error_past_a_failed_kill_and_shutdown(self):
        # An OpenVMM that outlives its kill can keep its output open, so its
        # reader doesn't stop either, and neither failure hides the other.
        interaction = self.StuckInteraction(b"booting\n", reader_stuck=True)
        with tempfile.TemporaryDirectory() as temporary:
            log_path = Path(temporary) / "process.log"
            with (
                patch.object(
                    openvmm_process, "InteractiveProcess", return_value=interaction
                ),
                self.outliving_kill() as terminate,
                self.assertRaises(RuntimeError) as raised,
                openvmm_process.OpenvmmProcess(["openvmm"], log_path) as process,
            ):
                process.wait_for(b"NEVER", 0.2)

            terminate.assert_called_once()
            # The failure path releases the process, and the block's exit
            # doesn't release it again.
            self.assertEqual(interaction.closes, 1)
            self.assertEqual(log_path.read_bytes(), b"booting\n")
        self.assertEqual(
            str(raised.exception),
            "marker b'NEVER' was not observed within 0.2s\n"
            "--- OpenVMM output ---\nbooting\n\n"
            f"--- cleanup failures ---\n- ProcessExitTimeout: {self.EXIT_TIMEOUT}\n"
            f"- {self.READER_STUCK}",
        )

    def test_an_openvmm_process_reports_a_failed_kill_and_shutdown_after_its_block(
        self,
    ):
        def stuck(*_arguments: object) -> CleanupAfterKillTests.StuckInteraction:
            return self.StuckInteraction(b"", reader_stuck=True)

        with (
            tempfile.TemporaryDirectory() as temporary,
            patch.object(openvmm_process, "InteractiveProcess", side_effect=stuck),
            self.outliving_kill(),
        ):
            log_path = Path(temporary) / "process.log"
            with self.assertRaises(benchmark.ProcessExitTimeout) as closed:
                with openvmm_process.OpenvmmProcess(["openvmm"], log_path):
                    pass
            with self.assertRaises(ValueError) as raised:
                with openvmm_process.OpenvmmProcess(["openvmm"], log_path):
                    raise ValueError("scenario failed")
        self.assertEqual(
            str(closed.exception),
            f"{self.EXIT_TIMEOUT}\n--- cleanup failures ---\n- {self.READER_STUCK}",
        )
        self.assertEqual(
            str(raised.exception),
            "scenario failed\n--- cleanup failures ---\n"
            f"- ProcessExitTimeout: {self.EXIT_TIMEOUT}\n- {self.READER_STUCK}",
        )

    def test_an_openvmm_process_reports_its_cleanup_after_an_errno_error(self):
        def stuck(*_arguments: object) -> CleanupAfterKillTests.StuckInteraction:
            return self.StuckInteraction(b"", reader_stuck=True)

        full = OSError(errno.ENOSPC, "No space left on device", "source.log")
        with (
            tempfile.TemporaryDirectory() as temporary,
            patch.object(openvmm_process, "InteractiveProcess", side_effect=stuck),
            self.outliving_kill(),
            self.assertRaises(OSError) as raised,
            openvmm_process.OpenvmmProcess(["openvmm"], Path(temporary) / "log"),
        ):
            raise full
        # The block's error can't show the failures, so the error that it
        # caused, which does, surfaces in its place.
        self.assertIs(raised.exception.__cause__, full)
        self.assertEqual(
            str(raised.exception),
            f"{full}\n--- cleanup failures ---\n"
            f"- ProcessExitTimeout: {self.EXIT_TIMEOUT}\n- {self.READER_STUCK}",
        )

    def test_an_openvmm_process_keeps_its_error_past_a_failed_transcript_close(
        self,
    ):
        class FullLog(io.BytesIO):
            """A transcript whose close fails to flush it."""

            def close(self) -> None:
                super().close()
                raise OSError(errno.ENOSPC, "No space left on device", "log")

        with (
            tempfile.TemporaryDirectory() as temporary,
            patch.object(
                openvmm_process,
                "InteractiveProcess",
                return_value=self.StuckInteraction(b"booting\n"),
            ),
            self.outliving_kill(),
            self.assertRaises(ValueError) as raised,
            openvmm_process.OpenvmmProcess(
                ["openvmm"], Path(temporary) / "log"
            ) as process,
        ):
            process._log.close()
            cast(Any, process)._log = FullLog()
            raise ValueError("scenario failed")
        full = OSError(errno.ENOSPC, "No space left on device", "log")
        self.assertEqual(
            str(raised.exception),
            "scenario failed\n--- cleanup failures ---\n"
            f"- ProcessExitTimeout: {self.EXIT_TIMEOUT}\n- OSError: {full}",
        )

    def test_a_failed_openvmm_launch_keeps_its_error_past_a_failed_kill_and_shutdown(
        self,
    ):
        interaction = self.StuckInteraction(b"", reader_stuck=True)
        with (
            tempfile.TemporaryDirectory() as temporary,
            patch.object(
                openvmm_process, "InteractiveProcess", return_value=interaction
            ),
            patch.object(
                openvmm_process.time, "sleep", side_effect=RuntimeError("interrupted")
            ),
            self.outliving_kill() as terminate,
            self.assertRaises(RuntimeError) as raised,
        ):
            log_path = Path(temporary) / "process.log"
            openvmm_process.OpenvmmProcess(["openvmm"], log_path, output_read_delay=1)

        terminate.assert_called_once()
        self.assertEqual(interaction.closes, 1)
        self.assertEqual(
            str(raised.exception),
            "interrupted\n--- cleanup failures ---\n"
            f"- ProcessExitTimeout: {self.EXIT_TIMEOUT}\n- {self.READER_STUCK}",
        )


AUTHORIZATION_VALUE = "Bearer placeholder-value"


class ReleaseTests(unittest.TestCase):
    def setUp(self) -> None:
        super().setUp()
        # Packaging reads nvx-rs; no test may read or replace the nvx-rs of
        # this checkout.
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.nvx_rs_path = Path(temporary.name) / nvx_rs.binary_path().name
        patcher = patch.object(nvx_rs, "binary_path", return_value=self.nvx_rs_path)
        patcher.start()
        self.addCleanup(patcher.stop)

    def test_nvx_rs_installs_the_scratch_template_that_packages_declare(self):
        # nvx-rs download installs the sandbox scratch template of a package
        # whose manifest gives its digest under the field and the name that
        # package writes.
        crate = BuildConstants.REPO_ROOT / "nvx-rs" / "src" / "host"
        install = (crate / "cli" / "download" / "install.rs").read_text(
            encoding="utf-8"
        )
        self.assertIn(
            'const SCRATCH_TEMPLATE_FIELD: &str = "scratch_template_sha256";',
            install,
        )
        guest = (crate / "artifacts" / "guest.rs").read_text(encoding="utf-8")
        self.assertIn(
            f'Self::Ubuntu => Some("{UbuntuBuildConstants.SCRATCH_TEMPLATE_NAME}"),',
            guest,
        )
        self.assertIn(
            UbuntuBuildConstants.SCRATCH_TEMPLATE_NAME,
            ReleaseBuildConstants.GUEST_ARTIFACT_NAMES,
        )

    def test_alpine_source_validation_rejects_malformed_manifest(self):
        with tempfile.TemporaryDirectory() as temporary:
            source_dir = Path(temporary)
            alpine_dir = source_dir / "alpine"
            alpine_dir.mkdir()
            (alpine_dir / "manifest.json").write_text("{", encoding="utf-8")

            with (
                patch.object(BuildConstants, "SOURCE_DIR", source_dir),
                self.assertRaisesRegex(
                    common.ScriptError,
                    "invalid collected Alpine source manifest",
                ),
            ):
                release._validate_alpine_sources([])

    def test_alpine_source_validation_checks_recorded_executables(self):
        with tempfile.TemporaryDirectory() as temporary:
            source_dir = Path(temporary)
            alpine_dir = source_dir / "alpine"
            recipe = alpine_dir / "recipes" / "c0ffee" / "main" / "foo"
            recipe.mkdir(parents=True)
            (recipe / "APKBUILD").write_bytes(b"pkgname=foo\n")
            (recipe / "foo.post-install").write_bytes(b"#!/bin/sh\n")
            installer = "recipes/c0ffee/main/foo/foo.post-install"
            current = AlpineBuildConstants.SOURCE_MANIFEST_FORMAT
            cases: dict[str, tuple[dict[str, object], str | None]] = {
                "recorded executable": (
                    {"format": current, "executables": [installer]},
                    None,
                ),
                "older format": (
                    {"format": 1, "executables": [installer]},
                    "unsupported manifest format",
                ),
                "missing executables": ({"format": current}, "invalid executables"),
                "unlisted executable": (
                    {"format": current, "executables": [f"{installer}.missing"]},
                    "not a checksummed recipe file",
                ),
                "executable outside recipes": (
                    {"format": current, "executables": ["manifest.json"]},
                    "not a checksummed recipe file",
                ),
            }
            for name, (document, error) in cases.items():
                (alpine_dir / "manifest.json").write_text(
                    json.dumps({"packages": [], **document}), encoding="utf-8"
                )
                common.write_sha256_sums(alpine_dir)
                with (
                    self.subTest(case=name),
                    patch.object(BuildConstants, "SOURCE_DIR", source_dir),
                ):
                    if error is None:
                        self.assertEqual(
                            release._validate_alpine_sources([]), {installer}
                        )
                        continue
                    with self.assertRaisesRegex(common.ScriptError, error):
                        release._validate_alpine_sources([])

    def test_alpine_source_archive_applies_recorded_modes(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source_dir = root / "sources"
            recipe = source_dir / "alpine" / "recipes" / "c0ffee" / "main" / "foo"
            recipe.mkdir(parents=True)
            for name in ("APKBUILD", "foo.post-install"):
                (recipe / name).write_bytes(b"#!/bin/sh\n")
            package_manifest = root / "initramfs.cpio.gz.packages.json"
            package_manifest.write_text("{}", encoding="utf-8")
            # Report every mode as Windows does, whatever the host stores.
            for path in (*source_dir.rglob("*"), package_manifest):
                path.chmod(0o777 if path.is_dir() else 0o666)
            output = root / "alpine-source.tar.gz"

            with (
                patch.object(BuildConstants, "SOURCE_DIR", source_dir),
                contextlib.redirect_stdout(io.StringIO()),
            ):
                release._alpine_source_archive(
                    output,
                    "1.0.0",
                    [package_manifest],
                    frozenset({"recipes/c0ffee/main/foo/foo.post-install"}),
                )

            with tarfile.open(output, "r:gz") as package:
                modes = {member.name: member.mode for member in package.getmembers()}
            prefix = "nvx-alpine-source-1.0.0"
            self.assertEqual(
                modes,
                {
                    f"{prefix}/sources": 0o755,
                    f"{prefix}/sources/recipes": 0o755,
                    f"{prefix}/sources/recipes/c0ffee": 0o755,
                    f"{prefix}/sources/recipes/c0ffee/main": 0o755,
                    f"{prefix}/sources/recipes/c0ffee/main/foo": 0o755,
                    f"{prefix}/sources/recipes/c0ffee/main/foo/APKBUILD": 0o644,
                    f"{prefix}/sources/recipes/c0ffee/main/foo/foo.post-install": (
                        0o755
                    ),
                    f"{prefix}/manifests/initramfs.cpio.gz.packages.json": 0o644,
                },
            )

    def test_asset_download_drops_credentials_across_origins(self):
        handler = common._CrossOriginRedirectHandler()
        request = urllib.request.Request(
            "https://api.github.invalid/assets/1",
            headers={"Authorization": AUTHORIZATION_VALUE, "Accept": "*/*"},
        )

        redirected = handler.redirect_request(
            request,
            io.BytesIO(b""),
            302,
            "Found",
            http.client.HTTPMessage(),
            "https://objects.github.invalid/assets/1?signature=abc",
        )
        same_host = handler.redirect_request(
            request,
            io.BytesIO(b""),
            302,
            "Found",
            http.client.HTTPMessage(),
            "https://api.github.invalid/assets/2",
        )
        downgraded = handler.redirect_request(
            request,
            io.BytesIO(b""),
            302,
            "Found",
            http.client.HTTPMessage(),
            "http://api.github.invalid/assets/3",
        )

        self.assertIsNotNone(redirected)
        self.assertIsNotNone(same_host)
        self.assertIsNotNone(downgraded)
        assert (
            redirected is not None and same_host is not None and downgraded is not None
        )
        self.assertIsNone(redirected.get_header("Authorization"))
        self.assertEqual(redirected.get_header("Accept"), "*/*")
        self.assertEqual(same_host.get_header("Authorization"), AUTHORIZATION_VALUE)
        self.assertIsNone(downgraded.get_header("Authorization"))

    def test_binary_package_stages_files_and_checksums(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            paths, kernel_inputs, revision = _write_release_fixture(root)
            build_dir = paths["build"]
            source_dir = paths["source"]
            openvmm_dir = paths["openvmm"]
            binary = paths["binary"]
            destination = root / "staged"
            stderr = io.StringIO()

            def artifact_path(name: str) -> Path:
                return build_dir / name

            with (
                patch.object(BuildConstants, "REPO_ROOT", root),
                patch.object(BuildConstants, "SOURCE_DIR", source_dir),
                patch.object(
                    UbuntuBuildConstants,
                    "PACKAGE_LOCK",
                    root / "ubuntu" / "packages.lock.json",
                ),
                patch.object(OpenVMMBuildConstants, "DIRECTORY", openvmm_dir),
                patch.object(
                    release,
                    "artifact_path",
                    side_effect=artifact_path,
                ),
                patch.object(release, "openvmm_binary_path", return_value=binary),
                patch.object(nvx_rs, "binary_path", return_value=paths["nvx_rs"]),
                patch.object(
                    release,
                    "kernel_provenance_inputs",
                    return_value=kernel_inputs,
                ),
                patch.object(
                    release,
                    "openvmm_git_state",
                    return_value=(revision, True),
                ),
                patch("sys.stderr", stderr),
            ):
                release.package_release(
                    version="1.0.0",
                    destination=destination,
                    include_source=False,
                    force=False,
                )

            self.assertTrue((destination / "bin" / binary.name).is_file())
            # The release build of nvx-rs ships beside OpenVMM, under the name
            # that Cargo gives it on this OS.
            packaged_nvx_rs = destination / "bin" / nvx_rs.binary_path().name
            self.assertEqual(packaged_nvx_rs.read_bytes(), paths["nvx_rs"].read_bytes())
            self.assertEqual(
                sorted(path.name for path in (destination / "bin").iterdir()),
                sorted((binary.name, packaged_nvx_rs.name)),
            )
            for name in ReleaseBuildConstants.GUEST_ARTIFACT_NAMES:
                self.assertTrue((destination / "guest" / name).is_file())
            self.assertTrue(
                (
                    destination / "provenance" / OpenVMMBuildConstants.PROVENANCE_NAME
                ).is_file()
            )
            self.assertTrue(
                (
                    destination / "provenance" / KernelBuildConstants.PROVENANCE_NAME
                ).is_file()
            )
            self.assertTrue(
                (
                    destination / "provenance" / InitramfsBuildConstants.PROVENANCE_NAME
                ).is_file()
            )
            manifest = json.loads(
                (destination / "SOURCE-MANIFEST.json").read_text(encoding="utf-8")
            )
            self.assertEqual(manifest["distribution"]["version"], "1.0.0")
            self.assertNotIn("guest_agent", manifest)
            self.assertEqual(manifest["openvmm"]["source_revision"], revision)
            self.assertEqual(
                manifest["openvmm"]["executable_sha256"],
                common.sha256_file(destination / "bin" / binary.name),
            )
            self.assertEqual(
                manifest["openvmm"]["microvm_abi_version"],
                2,
            )
            self.assertEqual(
                manifest["openvmm"]["control_session_protocol_version"],
                1,
            )
            self.assertEqual(
                manifest["openvmm"]["control_contract_revision"],
                "nvx-microvm-v2-control-v2",
            )
            self.assertEqual(
                manifest["linux"]["kernel_sha256"],
                common.sha256_file(destination / "guest" / "vmlinux"),
            )
            self.assertEqual(
                manifest["linux"]["config_sha256"],
                common.sha256_file(destination / "guest" / "vmlinux.config"),
            )
            self.assertEqual(
                manifest["azurelinux"]["initramfs_sha256"],
                common.sha256_file(
                    destination / "guest" / AzureLinuxBuildConstants.INITRAMFS_NAME
                ),
            )
            self.assertEqual(
                manifest["azurelinux"]["initramfs_package_manifest_sha256"],
                common.sha256_file(
                    destination
                    / "guest"
                    / AzureLinuxBuildConstants.PACKAGE_MANIFEST_NAME
                ),
            )
            # The package ships the sandbox scratch template, which the
            # manifest declares with its digest.
            self.assertEqual(
                manifest["ubuntu"]["scratch_template_sha256"],
                common.sha256_file(
                    destination / "guest" / UbuntuBuildConstants.SCRATCH_TEMPLATE_NAME
                ),
            )
            # The package ships the provenance of nvx-rs, which binds it to the
            # sources that build it, the Rust release, the target, and the
            # features, and the manifest records them with its digest.
            packaged_provenance = json.loads(
                (destination / "provenance" / nvx_rs.PROVENANCE_NAME).read_text(
                    encoding="utf-8"
                )
            )
            self.assertEqual(
                packaged_provenance,
                {
                    "format": 1,
                    "source_sha256": nvx_rs.source_sha256(root),
                    "toolchain": GuestRustBuildConstants.TOOLCHAIN,
                    "target": nvx_rs.release_target(),
                    "features": ["cli"],
                    "executable_sha256": common.sha256_file(packaged_nvx_rs),
                },
            )
            self.assertEqual(
                packaged_provenance["source_sha256"], nvx_rs.source_sha256()
            )
            self.assertEqual(
                manifest["nvx_rs"],
                {
                    "executable_sha256": common.sha256_file(packaged_nvx_rs),
                    "features": ["cli"],
                    "source_sha256": nvx_rs.source_sha256(root),
                    "target": nvx_rs.release_target(),
                    "toolchain": GuestRustBuildConstants.TOOLCHAIN,
                },
            )
            inventory = dict(common.verify_sha256_sums(destination).files)
            self.assertEqual(
                inventory[f"bin/{packaged_nvx_rs.name}"],
                common.sha256_file(paths["nvx_rs"]),
            )
            self.assertIn(f"provenance/{nvx_rs.PROVENANCE_NAME}", inventory)
            self.assertIn("binary-only package", stderr.getvalue())

    def test_source_package_omits_azure_linux_artifacts(self):
        for azurelinux_built in (True, False):
            with (
                self.subTest(azurelinux_built=azurelinux_built),
                tempfile.TemporaryDirectory() as temporary,
            ):
                root = Path(temporary)
                paths, kernel_inputs, revision = _write_release_fixture(root)
                build_dir = paths["build"]
                if not azurelinux_built:
                    for name in ReleaseBuildConstants.AZURELINUX_ARTIFACT_NAMES:
                        (build_dir / name).unlink()
                self._package_source_release_without_azure_linux(
                    root, paths, kernel_inputs, revision
                )

    def _package_source_release_without_azure_linux(
        self,
        root: Path,
        paths: dict[str, Path],
        kernel_inputs: dict[str, object],
        revision: str,
    ) -> None:
        build_dir = paths["build"]
        source_dir = paths["source"]
        openvmm_dir = paths["openvmm"]
        binary = paths["binary"]
        destination = root / "staged"
        stderr = io.StringIO()
        linux_source_archive = (
            source_dir
            / KernelBuildConstants.SOURCE_DIRECTORY_NAME
            / KernelBuildConstants.SOURCE_ARCHIVE_NAME
        )
        linux_source_archive.parent.mkdir(parents=True, exist_ok=True)
        linux_source_archive.write_bytes(b"linux-source")

        def artifact_path(name: str) -> Path:
            return build_dir / name

        def write_source_archive(output: Path, *_args: object) -> None:
            output.parent.mkdir(parents=True, exist_ok=True)
            output.write_bytes(output.name.encode("ascii"))

        with (
            patch.object(BuildConstants, "REPO_ROOT", root),
            patch.object(BuildConstants, "SOURCE_DIR", source_dir),
            patch.object(
                UbuntuBuildConstants,
                "PACKAGE_LOCK",
                root / "ubuntu" / "packages.lock.json",
            ),
            patch.object(OpenVMMBuildConstants, "DIRECTORY", openvmm_dir),
            patch.object(
                release,
                "artifact_path",
                side_effect=artifact_path,
            ),
            patch.object(release, "openvmm_binary_path", return_value=binary),
            patch.object(nvx_rs, "binary_path", return_value=paths["nvx_rs"]),
            patch.object(
                release,
                "kernel_provenance_inputs",
                return_value=kernel_inputs,
            ),
            patch.object(
                release,
                "openvmm_git_state",
                return_value=(revision, True),
            ),
            patch.object(release, "_validate_alpine_sources"),
            patch.object(release, "_validate_ubuntu_sources"),
            patch.object(release, "_validate_linux_source_archive"),
            patch.object(
                release,
                "_project_source_archive",
                side_effect=write_source_archive,
            ) as project_source_archive,
            patch.object(
                release,
                "_alpine_source_archive",
                side_effect=write_source_archive,
            ),
            patch.object(
                release,
                "_ubuntu_source_archive",
                side_effect=write_source_archive,
            ),
            patch("sys.stderr", stderr),
        ):
            release.package_release(
                version="1.0.0",
                destination=destination,
                include_source=True,
                force=False,
            )

        for name in ReleaseBuildConstants.AZURELINUX_ARTIFACT_NAMES:
            self.assertFalse((destination / "guest" / name).exists())
        for name in ReleaseBuildConstants.GUEST_ARTIFACT_NAMES:
            if name in ReleaseBuildConstants.AZURELINUX_ARTIFACT_NAMES:
                continue
            self.assertTrue((destination / "guest" / name).is_file())
        self.assertNotIn(
            build_dir / AzureLinuxBuildConstants.PACKAGE_MANIFEST_NAME,
            project_source_archive.call_args.args[2],
        )
        manifest = json.loads(
            (destination / "SOURCE-MANIFEST.json").read_text(encoding="utf-8")
        )
        self.assertNotIn("azurelinux", manifest)
        # Source-inclusive packages ship nvx-rs too; the project source
        # archive holds the sources that build it.
        packaged_nvx_rs = destination / "bin" / paths["nvx_rs"].name
        self.assertEqual(packaged_nvx_rs.read_bytes(), paths["nvx_rs"].read_bytes())
        self.assertEqual(
            manifest["nvx_rs"]["executable_sha256"],
            common.sha256_file(packaged_nvx_rs),
        )
        common.verify_sha256_sums(destination)
        self.assertIn("omits the Azure Linux guest", stderr.getvalue())

    def test_packages_require_the_release_build_of_nvx_rs(self):
        # A package ships the nvx-rs build for the release target of its
        # operating system, with the provenance that binds it to the current
        # sources. On Linux, that build is the static musl executable that
        # runs on every host, which a build for the host's own target is not.
        linux = nvx_rs.RELEASE_TARGETS["linux"]
        windows = nvx_rs.RELEASE_TARGETS["windows"]
        dynamic = _elf_file(
            ((1, b"code"), (3, b"/lib64/ld-linux-x86-64.so.2\0")), elf_type=3
        )
        mismatch = "from the current nvx-rs sources"
        with tempfile.TemporaryDirectory() as temporary:
            build_dir = Path(temporary) / "build"
            build_dir.mkdir()
            executable = Path(temporary) / "nvx-rs"
            provenance = build_dir / nvx_rs.PROVENANCE_NAME
            cases: tuple[
                tuple[str, bytes | None, dict[str, object] | None, str | None], ...
            ] = (
                (linux, _elf_file(), {}, None),
                (linux, _elf_file(elf_type=3), {}, None),
                (windows, b"MZ", {}, None),
                (linux, dynamic, {}, "is not static"),
                (linux, b"MZ", {}, f"invalid {linux} nvx-rs executable"),
                (linux, _elf_file(), {"target": windows}, f"as a {linux} build"),
                (windows, b"MZ", {"target": linux}, f"as a {windows} build"),
                (linux, _elf_file(), {"source_sha256": "0" * 64}, mismatch),
                (linux, _elf_file(), {"executable_sha256": "0" * 64}, mismatch),
                (linux, _elf_file(), {"toolchain": "1.0.0"}, mismatch),
                (linux, _elf_file(), {"features": []}, mismatch),
                (linux, _elf_file(), {"format": 2}, mismatch),
                (linux, _elf_file(), None, "nvx-rs build provenance not found"),
                (linux, None, {}, "nvx-rs release executable not found"),
            )
            for target, contents, changes, error in cases:
                with self.subTest(target=target, changes=changes, error=error):
                    executable.unlink(missing_ok=True)
                    provenance.unlink(missing_ok=True)
                    if contents is not None:
                        executable.write_bytes(contents)
                    if contents is not None and changes is not None:
                        record = nvx_rs.provenance_record(executable, target)
                        record.update(changes)
                        provenance.write_text(json.dumps(record), encoding="utf-8")
                    with (
                        patch.object(nvx_rs, "binary_path", return_value=executable),
                        patch.object(nvx_rs, "release_target", return_value=target),
                        patch.object(
                            release, "artifact_path", side_effect=build_dir.joinpath
                        ),
                    ):
                        if error is None:
                            self.assertEqual(
                                release._require_release_nvx_rs(),
                                (
                                    executable,
                                    provenance,
                                    json.loads(provenance.read_text(encoding="utf-8")),
                                ),
                            )
                            continue
                        with self.assertRaisesRegex(
                            common.ScriptError, re.escape(error)
                        ) as raised:
                            release._require_release_nvx_rs()
                    if error == "is not static":
                        # The message names the build that packages need.
                        self.assertIn(
                            f"--features cli --manifest-path nvx-rs/Cargo.toml "
                            f"--target {linux}",
                            str(raised.exception),
                        )
                    if error == mismatch:
                        self.assertIn(
                            "nvx.py record-nvx-rs-provenance", str(raised.exception)
                        )

    def test_runtime_provenance_validation_uses_required_paths(self):
        build_dir = Path("build")
        binary = Path("openvmm")
        nvx_rs_binary = Path("nvx-rs")

        def artifact_path(name: str) -> Path:
            return build_dir / name

        def require_file(path: Path, _description: str) -> Path:
            return path

        with (
            patch.object(release, "artifact_path", side_effect=artifact_path),
            patch.object(release, "openvmm_binary_path", return_value=binary),
            patch.object(nvx_rs, "find_binary", return_value=nvx_rs_binary),
            patch.object(
                release,
                "require_file",
                side_effect=require_file,
            ) as require,
            patch.object(release, "_validate_openvmm_provenance") as openvmm,
            patch.object(release, "_validate_kernel_provenance"),
            patch.object(release, "_validate_initramfs_provenance"),
            patch.object(release, "_validate_nvx_rs_provenance") as nvx_rs_check,
        ):
            release.validate_runtime_artifact_provenance()

        self.assertEqual(
            require.call_args_list[-4:],
            [
                call(
                    build_dir / OpenVMMBuildConstants.PROVENANCE_NAME,
                    "OpenVMM build provenance",
                ),
                call(
                    build_dir / KernelBuildConstants.PROVENANCE_NAME,
                    "kernel build provenance",
                ),
                call(
                    build_dir / InitramfsBuildConstants.PROVENANCE_NAME,
                    "initramfs build provenance",
                ),
                call(build_dir / nvx_rs.PROVENANCE_NAME, "nvx-rs build provenance"),
            ],
        )
        openvmm.assert_called_once_with(
            binary, build_dir / OpenVMMBuildConstants.PROVENANCE_NAME
        )
        # The nvx-rs that nvx.py runs, of any target.
        nvx_rs_check.assert_called_once_with(
            nvx_rs_binary, build_dir / nvx_rs.PROVENANCE_NAME, target=None
        )

    def test_runtime_provenance_validation_rejects_a_stale_nvx_rs(self):
        # nvx.py never rebuilds an nvx-rs that exists, so one left from
        # before a change of its sources, or that its provenance does not
        # describe, would run. The adversarial executor validates it first.
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            build_dir = root / "build"
            build_dir.mkdir()
            provenance = build_dir / nvx_rs.PROVENANCE_NAME
            other = root / "other-nvx-rs"
            other.write_bytes(b"another nvx-rs")

            def require_file(path: Path, _description: str) -> Path:
                return path

            def validate() -> None:
                with (
                    patch.object(
                        release, "artifact_path", side_effect=build_dir.joinpath
                    ),
                    patch.object(release, "openvmm_binary_path"),
                    patch.object(release, "require_file", side_effect=require_file),
                    patch.object(release, "_validate_openvmm_provenance"),
                    patch.object(release, "_validate_kernel_provenance"),
                    patch.object(release, "_validate_initramfs_provenance"),
                ):
                    release.validate_runtime_artifact_provenance()

            self.nvx_rs_path.write_bytes(b"nvx-rs")
            provenance.write_text(
                json.dumps(
                    nvx_rs.provenance_record(
                        self.nvx_rs_path, "x86_64-unknown-linux-gnu"
                    )
                ),
                encoding="utf-8",
            )
            with _without_nvx_rs_variable():
                validate()
                # A rebuild after the record.
                self.nvx_rs_path.write_bytes(b"rebuilt nvx-rs")
                with self.assertRaisesRegex(
                    common.ScriptError, "does not describe .* as a build from the"
                ):
                    validate()
            # The nvx-rs that NVX_RS names is the one that nvx.py runs.
            with (
                patch.dict(os.environ, {nvx_rs.VARIABLE: str(other)}),
                self.assertRaisesRegex(common.ScriptError, re.escape(str(other))),
            ):
                validate()
            provenance.write_text(
                json.dumps(nvx_rs.provenance_record(other, "x86_64-unknown-linux-gnu")),
                encoding="utf-8",
            )
            with patch.dict(os.environ, {nvx_rs.VARIABLE: str(other)}):
                validate()
            # A record of other sources.
            record = nvx_rs.provenance_record(other, "x86_64-unknown-linux-gnu")
            record["source_sha256"] = "0" * 64
            provenance.write_text(json.dumps(record), encoding="utf-8")
            with (
                patch.dict(os.environ, {nvx_rs.VARIABLE: str(other)}),
                self.assertRaisesRegex(common.ScriptError, "current nvx-rs sources"),
            ):
                validate()

